    "content": "{% extends \"base.html\" %}\n{% block title %}Transactions{% endblock %}\n{% block breadcrumb %}Transactions{% endblock %}\n{% block content %}\n<div class=\"page-heading heading-row\"><div><div class=\"eyebrow\">YOUR MONEY MOVES</div><h1>Transactions</h1><p>Every rupee, accounted for.</p></div><a class=\"btn btn-primary\" href=\"{{ url_for('transaction_form') }}\">＋ Add transaction</a></div>\n<section class=\"panel table-panel\">\n  <form class=\"filter-bar\" method=\"get\"><div class=\"search-field\"><span>⌕</span><input name=\"q\" value=\"{{ filters.get('q','') }}\" placeholder=\"Search descriptions…\"></div><select name=\"kind\"><option value=\"\">All types</option><option value=\"expense\" {{ 'selected' if filters.get('kind') == 'expense' }}>Expenses</option><option value=\"income\" {{ 'selected' if filters.get('kind') == 'income' }}>Income</option></select><select name=\"category\"><option value=\"\">All categories</option>{% for c in categories %}<option value=\"{{ c.id }}\" {{ 'selected' if filters.get('category')|string == c.id|string }}>{{ c.name }}</option>{% endfor %}</select><input type=\"date\" name=\"start\" aria-label=\"Start date\" value=\"{{ filters.get('start','') }}\"><input type=\"date\" name=\"end\" aria-label=\"End date\" value=\"{{ filters.get('end','') }}\"><button class=\"btn btn-secondary\" type=\"submit\">Filter</button><a class=\"clear-link\" href=\"{{ url_for('transactions') }}\">Clear</a></form>\n  <div class=\"table-scroll\"><table><thead><tr><th>TRANSACTION</th><th>CATEGORY</th><th>DATE</th><th>PAYMENT</th><th>AMOUNT</th><th></th></tr></thead><tbody>\n  {% for t in items %}<tr><td><div class=\"table-transaction\"><div class=\"category-symbol {{ 'symbol-income' if t.kind == 'income' else '' }}\">{{ '↗' if t.kind == 'income' else '↘' }}</div><div><strong>{{ t.description or t.category.name }}</strong><small>{{ t.kind|title }}</small></div></div></td><td><span class=\"category-pill\">{{ t.category.name }}</span></td><td>{{ t.transaction_date.strftime('%d %b %Y') }}</td><td>{{ t.payment_method }}</td><td class=\"money-cell {{ 'amount-income' if t.kind == 'income' else '' }}\">{{ '+' if t.kind == 'income' else '−' }}₹{{ \"{:,.2f}\".format(t.amount) }}</td><td><div class=\"row-actions\"><a href=\"{{ url_for('transaction_form', transaction_id=t.id) }}\" title=\"Edit\">✎</a><form method=\"post\" action=\"{{ url_for('transaction_delete', transaction_id=t.id) }}\" onsubmit=\"return confirm('Delete this transaction?')\">\n  <input type=\"hidden\" name=\"csrf_token\" value=\"{{ csrf_token() }}\"><button title=\"Delete\" aria-label=\"Delete transaction\">×</button></form></div></td></tr>{% else %}<tr><td colspan=\"6\"><div class=\"empty-state\"><div class=\"empty-icon\">↔</div><strong>No transactions found</strong><p>Try changing your filters or add a new transaction.</p><a class=\"btn btn-primary\" href=\"{{ url_for('transaction_form') }}\">Add transaction</a></div></td></tr>{% endfor %}\n  </tbody></table></div><div class=\"table-footer\"><span>{{ items|length }} transaction{{ '' if items|length == 1 else 's' }} found</span><a class=\"text-link\" href=\"{{ url_for('export_csv') }}\">↓ Export CSV</a></div>\n</section>\n{% endblock %}\n"
